using System.Text.RegularExpressions;
using Microsoft.EntityFrameworkCore;
using Zyven.Application;
using Zyven.Domain;
namespace Zyven.Infrastructure;

public sealed class PixRecoverySettingsService(ZyvenDbContext db, TenantAuthorization tenants, TimeProvider time)
{
    private static readonly Regex Variable = new(@"\{\{(buyer_name|offer_name|amount|pix_expiry|pix_code|checkout_url)\}\}", RegexOptions.Compiled);
    public async Task<PixRecoveryResponse> Get(Guid org, Guid offer, Guid user, CancellationToken ct) { await tenants.RequireMembership(org, user, ct); await Offer(org, offer, ct); var c = await db.PixRecoveryConfigurations.AsNoTracking().SingleOrDefaultAsync(x => x.OrganizationId == org && x.OfferId == offer, ct); return c is null ? new(Guid.Empty, false, 0, null, []) : await Response(c, 0, ct); }
    public async Task<PixRecoveryResponse> Save(Guid org, Guid offer, Guid user, PixRecoveryRequest request, CancellationToken ct) { await Writer(org, user, ct); await Offer(org, offer, ct); Validate(request); await using var tx = await db.Database.BeginTransactionAsync(ct); var c = await db.PixRecoveryConfigurations.SingleOrDefaultAsync(x => x.OrganizationId == org && x.OfferId == offer, ct); var now = time.GetUtcNow(); if (c is null) { c = new() { OrganizationId = org, OfferId = offer, CreatedAt = now }; db.Add(c); } else await db.PixRecoveryMessages.Where(x => x.ConfigurationId == c.Id && x.Version == 0).ExecuteDeleteAsync(ct); c.Enabled = request.Enabled; c.UpdatedAt = now; Add(c, 0, request.Messages, now); Audit(org, user, c.Id, "pix_recovery.draft_saved"); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return await Response(c, 0, ct); }
    public async Task<PixRecoveryResponse> Publish(Guid org, Guid offer, Guid user, CancellationToken ct) { await Writer(org, user, ct); await using var tx = await db.Database.BeginTransactionAsync(ct); var c = await db.PixRecoveryConfigurations.FromSqlInterpolated($"SELECT * FROM \"PixRecoveryConfigurations\" WHERE \"OrganizationId\"={org} AND \"OfferId\"={offer} FOR UPDATE").SingleOrDefaultAsync(ct) ?? throw new OrganizationException(400, "Salve a recuperação antes de publicar."); var rows = await db.PixRecoveryMessages.Where(x => x.ConfigurationId == c.Id && x.Version == 0).OrderBy(x => x.Position).ToListAsync(ct); var req = new PixRecoveryRequest(c.Enabled, rows.Select(x => new PixRecoveryMessageRequest(x.DelayMinutes, x.EmailText, x.TelegramText)).ToList()); Validate(req); var version = checked(c.PublishedVersion + 1); var now = time.GetUtcNow(); Add(c, version, req.Messages, now); c.PublishedVersion = version; c.PublishedAt = now; c.UpdatedAt = now; Audit(org, user, c.Id, "pix_recovery.published"); await db.SaveChangesAsync(ct); await tx.CommitAsync(ct); return await Response(c, 0, ct); }
    private void Add(PixRecoveryConfiguration c, int version, IReadOnlyList<PixRecoveryMessageRequest> rows, DateTimeOffset now) { for (var i = 0; i < rows.Count; i++) db.Add(new PixRecoveryMessage { OrganizationId = c.OrganizationId, ConfigurationId = c.Id, Version = version, Position = i, DelayMinutes = rows[i].DelayMinutes, EmailText = rows[i].EmailText.Trim(), TelegramText = rows[i].TelegramText.Trim(), CreatedAt = now }); }
    private async Task<PixRecoveryResponse> Response(PixRecoveryConfiguration c, int version, CancellationToken ct) { var rows = await db.PixRecoveryMessages.AsNoTracking().Where(x => x.ConfigurationId == c.Id && x.Version == version).OrderBy(x => x.Position).Select(x => new PixRecoveryMessageResponse(x.Position, x.DelayMinutes, x.EmailText, x.TelegramText)).ToListAsync(ct); return new(c.Id, c.Enabled, c.PublishedVersion, c.PublishedAt, rows); }
    private static void Validate(PixRecoveryRequest r) { if (r.Messages is null || r.Messages.Count is < 1 or > 5) throw Bad("Configure de 1 a 5 lembretes."); var previous = 0; foreach (var m in r.Messages) { if (m.DelayMinutes <= previous || m.DelayMinutes > 43200) throw Bad("Os atrasos devem ser crescentes e limitados a 30 dias."); if (!Text(m.EmailText) || !Text(m.TelegramText)) throw Bad("Revise os textos e as variáveis dos lembretes."); previous = m.DelayMinutes; } }
    private static bool Text(string? s) => s is { Length: > 0 and <= 4000 } && !Regex.Replace(s, Variable.ToString(), "").Contains("{{", StringComparison.Ordinal);
    private async Task Writer(Guid org, Guid user, CancellationToken ct) { var m = await tenants.RequireMembership(org, user, ct); if (m.Role is not (OrganizationRoles.Owner or OrganizationRoles.Admin or OrganizationRoles.Operator)) throw new OrganizationException(403, "Seu papel não permite esta alteração."); }
    private async Task Offer(Guid org, Guid offer, CancellationToken ct) { if (!await db.Offers.AnyAsync(x => x.OrganizationId == org && x.Id == offer, ct)) throw new OrganizationException(404, "Oferta não encontrada."); }
    private void Audit(Guid org, Guid user, Guid target, string action) => db.Add(new AuditLog { OrganizationId = org, ActorUserId = user, TargetId = target, Action = action, OccurredAt = time.GetUtcNow() }); private static OrganizationException Bad(string m) => new(400, m);
}
